import{_ as a,C as s,o as r,c as l,a3 as d,j as n,E as i}from"./chunks/framework.B9qR_F1m.js";const A=JSON.parse('{"title":"Ablauf als Mission Designer","description":"","frontmatter":{},"headers":[],"relativePath":"ablaeufe/designer.md","filePath":"ablaeufe/designer.md"}'),o={name:"ablaeufe/designer.md"},h={class:"tiles"},u={class:"tile",href:"../dcs/speichern"},g={class:"tile-icon"},f={class:"tile",href:"../gemeinsam/teilen"},c={class:"tile-icon"},b={class:"tile",href:"../dcs/speichern#export"},p={class:"tile-icon"};function m(k,e,S,P,_,F){const t=s("Icon");return r(),l("div",null,[e[6]||(e[6]=d('<h1 id="ablauf-als-mission-designer" tabindex="-1">Ablauf als Mission Designer <a class="header-anchor" href="#ablauf-als-mission-designer" aria-label="Permalink to &quot;Ablauf als Mission Designer&quot;">​</a></h1><p>Du hast im Mission Editor eine Mission gebaut. Mit Shardwing machst du daraus ein Briefing-Paket, das deine Piloten ohne Vorwissen fliegen können. Diese Seite ist der rote Faden; jeder Schritt verlinkt auf die Details. Zum Abhaken gibt es die <a href="./checklisten">Checklisten</a>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.miz ─► Intel ─► Flights ─► Timing ─► Kneeboards ─► Speichern / Teilen ─► DCS</span></span></code></pre></div><h2 id="_1-·-mission-vorbereiten-im-mission-editor" tabindex="-1">1 · Mission vorbereiten (im Mission Editor) <a class="header-anchor" href="#_1-·-mission-vorbereiten-im-mission-editor" aria-label="Permalink to &quot;1 · Mission vorbereiten (im Mission Editor)&quot;">​</a></h2><p>Shardwing ergänzt eine bestehende Mission. Im Mission Editor legst du fest:</p><ul><li>Flights mit Flugzeugtyp, Startplatz, Callsign, Funkfrequenz und Route – <strong>Client</strong> oder <strong>Player</strong> für alle, die Menschen fliegen sollen.</li><li>Gegner, SAM-Stellungen, Tanker, AWACS.</li><li>Wetter und Startzeit.</li></ul><p>SAMs musst du nicht ordentlich benennen – das übernimmt später das <a href="/bereiche/iads">IADS-Werkzeug</a>.</p><h2 id="_2-·-lage-verstehen-–-ubersicht" tabindex="-1">2 · Lage verstehen – Übersicht <a class="header-anchor" href="#_2-·-lage-verstehen-–-ubersicht" aria-label="Permalink to &quot;2 · Lage verstehen – Übersicht&quot;">​</a></h2><p>Öffne die Mission und schau in die <a href="/bereiche/uebersicht">Übersicht</a>. Jeder Flight bekommt dort <strong>Prüfungen</strong>: doppelte Frequenzen, fehlende Joker/Bingo, Timing-Probleme. Rot heißt „prüfen“.</p><h2 id="_3-·-intel-freigeben" tabindex="-1">3 · Intel freigeben <a class="header-anchor" href="#_3-·-intel-freigeben" aria-label="Permalink to &quot;3 · Intel freigeben&quot;">​</a></h2><p>Im Bereich <a href="/bereiche/intel">Intel</a> entscheidest du, <strong>was die Piloten wissen</strong>. Alle SAMs sind zuerst verborgen. Gib Stellungen für alle oder nur für einzelne Flights frei, ergänze eigene Threats (z. B. eine vermutete SA-6). Nur Freigegebenes landet auf Karte, Lineup Card, Cartridge und F10.</p><h2 id="_4-·-flights-ausplanen" tabindex="-1">4 · Flights ausplanen <a class="header-anchor" href="#_4-·-flights-ausplanen" aria-label="Permalink to &quot;4 · Flights ausplanen&quot;">​</a></h2><p>Für jeden Flight im Bereich <a href="/bereiche/flights">Flights</a>:</p><table tabindex="0"><thead><tr><th>Reiter</th><th>Was du tust</th></tr></thead><tbody><tr><td><a href="/bereiche/flights#route">Route</a></td><td>Wegpunkte prüfen, Höhen und Geschwindigkeiten anpassen</td></tr><tr><td><a href="/bereiche/flights#zeiten">Zeiten</a></td><td>Push, Fenster und Sollzeiten des Flights – dasselbe wie im Timing</td></tr><tr><td><a href="/bereiche/flights#units-funk">Units &amp; Funk</a></td><td>Gruppenfrequenz setzen, Tail Numbers, Laser-Codes, Funk-Presets ansehen</td></tr><tr><td><a href="/bereiche/beladung">Beladung</a></td><td>Waffen pro Station, Fuel, Chaff/Flare, Gun</td></tr><tr><td><a href="/bereiche/dtc">DTC</a></td><td>Cartridge <strong>Neu aus Route</strong> – Steerpoints, Threats, Geo Lines, Funk</td></tr><tr><td><a href="/bereiche/angriff">Angriff</a></td><td>Pop-up-, Toss- oder Standoff-Angriff vom Ziel aus rechnen</td></tr><tr><td><a href="/bereiche/lineup-card">Lineup Card</a></td><td>Joker/Bingo, Hinweise, Kartenseiten – und einbetten</td></tr><tr><td><a href="/bereiche/flights#status">Status</a></td><td>Prüfungen ansehen, Freigaben für Lead und Wingman setzen</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Eigene Callsigns</p><p>In der <a href="/bereiche/uebersicht#callsigns-aufgaben">Übersicht</a> gibst du jedem Flight einen richtigen Callsign (z. B. „VIPER 1“) und eine Aufgabe (SEAD, BARCAP …). Das ändert nur die Unterlagen, nicht die .miz.</p></div><h2 id="_5-·-timing-abstimmen" tabindex="-1">5 · Timing abstimmen <a class="header-anchor" href="#_5-·-timing-abstimmen" aria-label="Permalink to &quot;5 · Timing abstimmen&quot;">​</a></h2><p>Im Bereich <a href="/bereiche/timing">Timing</a> setzt du die <strong>H-Hour</strong> und hängst jeden Flight daran: TOT-Fenster für Striker, Vul-Zeiten für CAP und Escort, SEAD-Fenster für die Weasels, Push-Punkte, Tanker-Slots. Die Sync-Matrix zeigt sofort, wer laut Route zu früh oder zu spät ist – und rechnet rückwärts, wann jeder anlassen muss.</p><h2 id="_6-·-kneeboards-fur-alle" tabindex="-1">6 · Kneeboards für alle <a class="header-anchor" href="#_6-·-kneeboards-fur-alle" aria-label="Permalink to &quot;6 · Kneeboards für alle&quot;">​</a></h2><p>Im Bereich <a href="/bereiche/kneeboards">Kneeboards</a>:</p><ul><li><strong>Comm Plan</strong> anlegen: Netze, Frequenzen, Preset-Kanäle. Ein Knopf trägt sie in alle Cartridges ein.</li><li>Seiten aus Vorlagen: Deckblatt, Auftrag, SPINS, Abnormals, Wetter, Lagekarte, Paket-Tabelle, Index.</li><li>Grafiken für F10 im Bereich <a href="/bereiche/planung">Planung</a>: CAP-Stationen, FLOT, Kill Boxes.</li></ul><h2 id="_7-·-prufen-aus-sicht-der-piloten" tabindex="-1">7 · Prüfen aus Sicht der Piloten <a class="header-anchor" href="#_7-·-prufen-aus-sicht-der-piloten" aria-label="Permalink to &quot;7 · Prüfen aus Sicht der Piloten&quot;">​</a></h2><p>Oben rechts über die <strong>Rolle</strong> schaust du dir die Mission als Lead oder Wingman eines Flights an – mit genau dem, was er sehen darf. So fällt auf, wenn eine Bedrohung fehlt oder zu viel verrät. (<a href="/gemeinsam/rollen">Rollen</a>)</p><h2 id="_8-·-ausliefern" tabindex="-1">8 · Ausliefern <a class="header-anchor" href="#_8-·-ausliefern" aria-label="Permalink to &quot;8 · Ausliefern&quot;">​</a></h2><p>Zwei Wege, auch kombinierbar:</p>',24)),n("div",h,[n("a",u,[n("span",g,[i(t,{name:"save"})]),e[0]||(e[0]=n("span",{class:"tile-title"},"Speichern",-1)),e[1]||(e[1]=n("span",{class:"tile-text"},"Alles in die .miz: Cartridges, Kneeboards, Zeichnungen, Beladung. Mission auf den DCS-Server – fertig.",-1))]),n("a",f,[n("span",c,[i(t,{name:"users"})]),e[2]||(e[2]=n("span",{class:"tile-title"},"Teilen",-1)),e[3]||(e[3]=n("span",{class:"tile-text"},"Mission auf den Shardwing-Server, Piloten tragen sich ein und planen ihren Flight selbst.",-1))]),n("a",b,[n("span",p,[i(t,{name:"file-down"})]),e[4]||(e[4]=n("span",{class:"tile-title"},"Export",-1)),e[5]||(e[5]=n("span",{class:"tile-text"},"PDF fürs Briefing, Kneeboard-ZIP für Saved Games oder OpenKneeboard.",-1))])])])}const z=a(o,[["render",m]]);export{A as __pageData,z as default};
